mapper.sql:
FROM benefit_theater_stock s
INNER JOIN cinema c ON c.id = s.cinema_id AND c.deleted = 0
LEFT JOIN brand b ON b.id = c.brand_id AND b.deleted = 0
WHERE s.deleted = 0
  AND s.benefit_id = #{q.benefitId}

    AND c.id IN

        #{cid}



    AND c.region_id = #{q.regionId}


    AND c.prefecture_id = #{q.prefectureId}


    AND c.name ILIKE '%' || #{q.keyword} || '%'

mst.deleted = 0
AND mst.cinema_id = c.id
AND mst.movie_id = #{q.movieId}


        AND mst.re_release_id = #{q.reReleaseId}


        AND mst.re_release_id IS NULL


AND mst.start_time::timestamp >= now()
